1	import { useState, useRef, useEffect, useMemo } from 'react';
2	import type { Event } from '../../types/Event';
3	import type { Round } from '../../types/Round';
4	import { categoryForAction, colorForAction, iconForAction, matchFilter, formatFrameClock, type SpanKind } from './taxonomy';
5	
6	const TL = { ruler: 26, round: 30, state: 30, span: 26, lane: 46, head: 132 };
7	
8	const SPAN_COLOR: Record<SpanKind, string> = {
9	  round: 'var(--green-500)',
10	  corner_swap: 'var(--purple-600)',
11	  excluded: 'var(--text-muted)',
12	};
13	
14	function useMeasure(): [React.RefObject<HTMLDivElement | null>, number] {
15	  const ref = useRef<HTMLDivElement>(null);
16	  const [w, setW] = useState(0);
17	  useEffect(() => {
18	    if (!ref.current) return;
19	    const ro = new ResizeObserver(es => { for (const e of es) setW(e.contentRect.width); });
20	    ro.observe(ref.current);
21	    return () => ro.disconnect();
22	  }, []);
23	  return [ref, w];
24	}
25	
26	function fmtSec(s: number): string {
27	  const m = Math.floor(s / 60);
28	  const sec = Math.floor(s % 60);
29	  return `${m}:${String(sec).padStart(2, '0')}`;
30	}
31	
32	function laneFor(e: Event): 'red' | 'blue' | null {
33	  if (e.corner === 0) return 'red';
34	  if (e.corner === 1) return 'blue';
35	  return null;
36	}
37	
38	interface Hover { e: Event; x: number; color: string; text: string }
39	
40	interface ClipProps {
41	  e: Event;
42	  x: number;
43	  color: string;
44	  text: string;
45	  flash: boolean;
46	  selected: boolean;
47	  onSeek: (frame: number) => void;
48	  onSelect: (id: number) => void;
49	  onHover: (h: Hover | null) => void;
50	}
51	
52	function Clip({ e, x, color, text, flash, selected, onSeek, onSelect, onHover }: ClipProps) {
53	  return (
54	    <button
55	      className="tl-clip"
56	      onPointerDown={ev => ev.stopPropagation()}
57	      onClick={ev => { ev.stopPropagation(); onSeek(e.frame); onSelect(e.id); }}
58	      onMouseEnter={ev => onHover({ e, x: (ev.currentTarget as HTMLElement).offsetLeft, color, text })}
59	      onMouseLeave={() => onHover(null)}
60	      title={selected ? `${text} · Delete to remove` : text}
61	      style={{
62	        position: 'absolute', left: x - 11, top: (TL.lane - 30) / 2, width: 22, height: 30, borderRadius: 6,
63	        display: 'grid', placeItems: 'center', cursor: 'pointer', zIndex: flash || selected ? 6 : 4, padding: 0,
64	        transition: 'transform .1s',
65	        border: `1px solid color-mix(in srgb, ${color} ${flash || selected ? 90 : 55}%, transparent)`,
66	        background: `color-mix(in srgb, ${color} ${flash || selected ? 34 : 18}%, var(--surface-inner))`,
67	        boxShadow: selected ? `0 0 0 2px #fff, 0 0 0 3.5px ${color}` : flash ? `0 0 0 1.5px ${color}` : 'none',
68	        animation: 'feed-in .25s ease-out',
69	      }}
70	    >
71	      <span className="material-symbols-outlined" style={{ fontSize: 16, color }}>{iconForAction(e.action)}</span>
72	    </button>
73	  );
74	}
75	
76	interface AnnotationTimelineProps {
77	  events: Event[];
78	  spans: Event[];
79	  rounds: Round[];
80	  duration: number;
81	  fps: number;
82	  currentFrame: number;
83	  onSeek: (frame: number) => void;
84	  onSetPlaying: (playing: boolean) => void;
85	  onUpdateSpan: (id: number, patch: { frame?: number; end_frame?: number }) => void;
86	  onDeleteSpan: (id: number) => void;
87	  onAddRound: () => void;
88	  flashId: number | null;
89	  selectedEventId: number | null;
90	  onSelectEvent: (id: number | null) => void;
91	  filter: string;
92	  redName: string;
93	  blueName: string;
94	  describe: (e: Event) => string;
95	}
96	
97	export default function AnnotationTimeline({
98	  events, spans, rounds, duration, fps, currentFrame, onSeek, onSetPlaying, onUpdateSpan, onDeleteSpan, onAddRound,
99	  flashId, selectedEventId, onSelectEvent, filter, redName, blueName, describe,
100	}: AnnotationTimelineProps) {
101	  const [zoom, setZoom] = useState(1);
102	  const [hover, setHover] = useState<Hover | null>(null);
103	  const [scrollRef, scrollW] = useMeasure();
104	  const draggingRef = useRef(false);
105	
106	  const time = (currentFrame - 1) / fps;
107	  const frameFor = (t: number) => Math.max(1, Math.round(t * fps) + 1);
108	  const xFor = (frame: number) => ((frame - 1) / fps) * pxPerSec;
109	
110	  const fitPx = scrollW > 0 ? scrollW / Math.max(duration, 1) : 2.2;
111	  const pxPerSec = fitPx * zoom;
112	  const W = duration * pxPerSec;
113	  const spansTop = TL.ruler + TL.round + TL.state;
114	  const lanesTop = spansTop + TL.span * 2;
115	  const totalH = lanesTop + TL.lane * 2;
116	  const boxH = totalH + 14;
117	
118	  // Live edge being dragged, so the block redraws smoothly before the PUT commits.
119	  const dragRef = useRef<{ id: number; edge: 'start' | 'end' } | null>(null);
120	  const [dragFrame, setDragFrame] = useState<number | null>(null);
121	
122	  const fil = (e: Event) => matchFilter(categoryForAction(e.action), filter);
123	  const redEv = events.filter(e => laneFor(e) === 'red' && e.action !== 'fight_end' && fil(e));
124	  const blueEv = events.filter(e => laneFor(e) === 'blue' && e.action !== 'fight_end' && fil(e));
125	  const roundEv = events.filter(e => categoryForAction(e.action) === 'round' || e.action === 'fight_end');
126	  // Everything after fight_end is dead air (celebration, doctor check, corner
127	  // talk) — the round span and the last state segment are visually capped
128	  // here to end there, so the timeline actually looks like the fight is
129	  // over. The underlying round span's real end_frame is untouched (only the
130	  // auto-created `excluded` span makes the tail harmless for scoring/export
131	  // — see Annotate.tsx's confirmFightEnd); this is display-only.
132	  const fightEndFrame = events.find(e => e.action === 'fight_end')?.frame ?? null;
133	  const stateEv = useMemo(
134	    () => events.filter(e => categoryForAction(e.action) === 'state').sort((a, b) => a.frame - b.frame),
135	    [events],
136	  );
137	  const segs = stateEv
138	    .map((e, i) => {
139	      const rawT1 = i + 1 < stateEv.length ? (stateEv[i + 1].frame - 1) / fps : duration;
140	      const t1 = fightEndFrame != null ? Math.min(rawT1, (fightEndFrame - 1) / fps) : rawT1;
141	      return {
142	        id: e.id,
143	        t0: (e.frame - 1) / fps,
144	        t1,
145	        state: e.action === 'state_clinch' ? 'CLINCH' : e.action === 'state_ground' ? 'GROUND' : 'STRIKING',
146	      };
147	    })
148	    .filter(s => s.t1 >= s.t0); // drop a segment that starts entirely after fight_end
149	
150	  // Same display-only capping as the state segments above: the round block
151	  // that contains fight_end is drawn ending there instead of at its real
152	  // (now-stale) end_frame. Edge-drag still targets the real span by id, so
153	  // dragging the end handle still writes the true end_frame — it just
154	  // starts from the visually-capped position rather than the stale one.
155	  const roundSpans = spans
156	    .filter(s => s.kind === 'round')
157	    .map(s => (
158	      fightEndFrame != null && s.end_frame != null &&
159	      s.frame <= fightEndFrame && fightEndFrame < s.end_frame
160	        ? { ...s, end_frame: fightEndFrame }
161	        : s
162	    ));
163	  const cornerSwapSpans = spans.filter(s => s.kind === 'corner_swap');
164	  const excludedSpans = spans.filter(s => s.kind === 'excluded');
165	
166	  const targets = [5, 10, 15, 30, 60, 120, 180];
167	  const tickEvery = targets.find(s => s * pxPerSec >= 64) || 240;
168	  const ticks: number[] = [];
169	  for (let t = 0; t <= duration; t += tickEvery) ticks.push(t);
170	
171	  const scrubRef = useRef<(clientX: number) => void>(() => {});
172	  scrubRef.current = (clientX: number) => {
173	    const el = scrollRef.current;
174	    if (!el) return;
175	    const r = el.getBoundingClientRect();
176	    const t = (clientX - r.left + el.scrollLeft) / pxPerSec;
177	    onSeek(frameFor(Math.max(0, Math.min(duration, t))));
178	  };
179	  useEffect(() => {
180	    const move = (e: PointerEvent) => { if (draggingRef.current) scrubRef.current(e.clientX); };
181	    const up = () => { draggingRef.current = false; };
182	    window.addEventListener('pointermove', move);
183	    window.addEventListener('pointerup', up);
184	    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
185	  }, []);
186	  const startScrub = (e: React.PointerEvent) => {
187	    draggingRef.current = true;
188	    onSetPlaying(false);
189	    onSelectEvent(null); // clicking the background/ruler deselects whatever clip was selected
190	    scrubRef.current(e.clientX);
191	  };
192	
193	  // Edge-drag for span blocks (round / corner_swap / excluded resize handles).
194	  useEffect(() => {
195	    const move = (e: PointerEvent) => {
196	      const d = dragRef.current;
197	      const el = scrollRef.current;
198	      if (!d || !el) return;
199	      const r = el.getBoundingClientRect();
200	      const t = (e.clientX - r.left + el.scrollLeft) / pxPerSec;
201	      setDragFrame(frameFor(Math.max(0, Math.min(duration, t))));
202	    };
203	    const up = () => {
204	      const d = dragRef.current;
205	      if (d && dragFrame != null) {
206	        onUpdateSpan(d.id, d.edge === 'start' ? { frame: dragFrame } : { end_frame: dragFrame });
207	      }
208	      dragRef.current = null;
209	      setDragFrame(null);
210	    };
211	    window.addEventListener('pointermove', move);
212	    window.addEventListener('pointerup', up);
213	    return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
214	    // eslint-disable-next-line react-hooks/exhaustive-deps
215	  }, [pxPerSec, duration, dragFrame]);
216	  const startEdgeDrag = (id: number, edge: 'start' | 'end') => (e: React.PointerEvent) => {
217	    e.stopPropagation();
218	    onSetPlaying(false);
219	    dragRef.current = { id, edge };
220	  };
221	
222	  useEffect(() => {
223	    const el = scrollRef.current;
224	    if (!el) return;
225	    const x = xFor(currentFrame);
226	    const L = el.scrollLeft;
227	    const R = L + el.clientWidth;
228	    if (x < L + 48 || x > R - 48) el.scrollLeft = x - el.clientWidth / 2;
229	    // eslint-disable-next-line react-hooks/exhaustive-deps
230	  }, [time, pxPerSec]);
231	
232	  const TrackHead = ({ h, children, top }: { h: number; children: React.ReactNode; top: number }) => (
233	    <div style={{
234	      position: 'absolute', top, left: 0, height: h, width: TL.head, display: 'flex', alignItems: 'center', gap: 8,
235	      padding: '0 12px', boxSizing: 'border-box', borderBottom: '1px solid var(--border-subtle)',
236	      borderRight: '1px solid var(--border-glass)', background: 'var(--surface-inner)',
237	    }}>{children}</div>
238	  );
239	
240	  const playX = xFor(currentFrame);
241	
242	  // A span block with draggable edges (round/corner_swap) or a plain block
243	  // with a delete button (corner_swap/excluded). `end_frame == null` means
244	  // the start/end toggle is still open — draw it running to the playhead.
245	  const SpanBlock = ({ s, top, h, deletable }: { s: Event; top: number; h: number; deletable: boolean }) => {
246	    const dragging = dragRef.current?.id === s.id;
247	    const start = dragging && dragRef.current?.edge === 'start' && dragFrame != null ? dragFrame : s.frame;
248	    const end = dragging && dragRef.current?.edge === 'end' && dragFrame != null
249	      ? dragFrame
250	      : s.end_frame ?? currentFrame;
251	    const open = s.end_frame == null;
252	    const x0 = xFor(Math.min(start, end));
253	    const w = Math.max(4, xFor(Math.max(start, end)) - x0);
254	    // SpanBlock only ever receives round/corner_swap/excluded rows (see the
255	    // `spans` prop, always pre-filtered to kind !== 'point' by the caller).
256	    const c = SPAN_COLOR[s.kind as SpanKind];
257	    return (
258	      <div
259	        style={{
260	          position: 'absolute', top, left: x0, width: w, height: h, borderRadius: 5, zIndex: 3,
261	          background: `color-mix(in srgb, ${c} ${open ? 10 : 16}%, transparent)`,
262	          border: `1px solid color-mix(in srgb, ${c} ${open ? 55 : 38}%, transparent)`,
263	          borderStyle: open ? 'dashed' : 'solid',
264	          display: 'flex', alignItems: 'center', overflow: 'hidden',
265	        }}
266	        title={s.value ? `${s.kind} — ${s.value}` : s.kind}
267	      >
268	        <div
269	          onPointerDown={startEdgeDrag(s.id, 'start')}
270	          title="Drag to move the start"
271	          style={{
272	            position: 'absolute', left: -5, top: 0, width: 13, height: '100%', cursor: 'ew-resize', zIndex: 4,
273	            display: 'flex', alignItems: 'center', justifyContent: 'flex-end', paddingRight: 4,
274	          }}
275	        >
276	          <span style={{ width: 2, height: '55%', borderRadius: 1, background: `color-mix(in srgb, ${c} 70%, transparent)` }} />
277	        </div>
278	        {!open && (
279	          <div
280	            onPointerDown={startEdgeDrag(s.id, 'end')}
281	            title="Drag to move the end"
282	            style={{
283	              position: 'absolute', right: -5, top: 0, width: 13, height: '100%', cursor: 'ew-resize', zIndex: 4,
284	              display: 'flex', alignItems: 'center', justifyContent: 'flex-start', paddingLeft: 4,
285	            }}
286	          >
287	            <span style={{ width: 2, height: '55%', borderRadius: 1, background: `color-mix(in srgb, ${c} 70%, transparent)` }} />
288	          </div>
289	        )}
290	        {w > 30 && (
291	          <span style={{ fontFamily: 'var(--mono)', fontSize: 10, fontWeight: 500, color: c, whiteSpace: 'nowrap', paddingLeft: 8, pointerEvents: 'none' }}>
292	            {s.kind === 'round' ? `R${s.value ?? ''}` : s.value ?? s.kind.toUpperCase()}{open ? '…' : ''}
293	          </span>
294	        )}
295	        {deletable && !open && (
296	          <button
297	            onPointerDown={ev => ev.stopPropagation()}
298	            onClick={ev => { ev.stopPropagation(); onDeleteSpan(s.id); }}
299	            title="Delete"
300	            style={{
301	              position: 'absolute', right: 2, top: '50%', transform: 'translateY(-50%)', width: 14, height: 14,
302	              borderRadius: 4, border: 'none', background: 'rgba(0,0,0,0.35)', color: c, cursor: 'pointer',
303	              display: 'grid', placeItems: 'center', padding: 0, zIndex: 5,
304	            }}
305	          >
306	            <span className="material-symbols-outlined" style={{ fontSize: 10 }}>close</span>
307	          </button>
308	        )}
309	      </div>
310	    );
311	  };
312	
313	  return (
314	    <div style={{ display: 'flex', position: 'relative', height: boxH, borderRadius: 8, overflow: 'hidden', border: '1px solid var(--border-glass)' }}>
315	      <div style={{ position: 'relative', width: TL.head, flexShrink: 0, background: 'var(--surface-inner)', zIndex: 8 }}>
316	        <div style={{
317	          position: 'absolute', top: 0, height: TL.ruler, width: TL.head, borderBottom: '1px solid var(--border-glass)',
318	          borderRight: '1px solid var(--border-glass)', display: 'flex', alignItems: 'center', padding: '0 12px',
319	          fontFamily: 'var(--mono)', fontSize: 10.5, fontWeight: 500, color: 'var(--text-muted)',
320	        }}>Tracks</div>
321	        <TrackHead top={TL.ruler} h={TL.round}>
322	          <span className="material-symbols-outlined" style={{ fontSize: 15, color: 'var(--green-500)' }}>flag</span>
323	          <span style={{ fontSize: 11.5, fontWeight: 500, color: 'var(--text-secondary)' }}>Rounds</span>
324	          <button
325	            className="icon-btn"
326	            onClick={onAddRound}
327	            title="New round at the playhead (K)"
328	            style={{ width: 20, height: 20, marginLeft: 'auto' }}
329	          >
330	            <span className="material-symbols-outlined" style={{ fontSize: 15 }}>add</span>
331	          </button>
332	        </TrackHead>
333	        <TrackHead top={TL.ruler + TL.round} h={TL.state}>
334	          <span className="material-symbols-outlined" style={{ fontSize: 15, color: 'var(--slate-400)' }}>change_circle</span>
335	          <span style={{ fontSize: 11.5, fontWeight: 500, color: 'var(--text-secondary)' }}>State</span>
336	        </TrackHead>
337	        <TrackHead top={spansTop} h={TL.span}>
338	          <span className="material-symbols-outlined" style={{ fontSize: 14, color: 'var(--purple-600)' }}>swap_horiz</span>
339	          <span style={{ fontSize: 11.5, fontWeight: 500, color: 'var(--text-secondary)' }}>Corner swap</span>
340	        </TrackHead>
341	        <TrackHead top={spansTop + TL.span} h={TL.span}>
342	          <span className="material-symbols-outlined" style={{ fontSize: 14, color: 'var(--text-muted)' }}>visibility_off</span>
343	          <span style={{ fontSize: 11.5, fontWeight: 500, color: 'var(--text-secondary)' }}>Excluded</span>
344	        </TrackHead>
345	        <TrackHead top={lanesTop} h={TL.lane}>
346	          <span style={{ width: 8, height: 8, borderRadius: 2, background: 'var(--f-red)' }} />
347	          <span style={{ fontSize: 12, fontWeight: 600, color: 'var(--text-primary)' }}>{redName}</span>
348	        </TrackHead>
349	        <TrackHead top={lanesTop + TL.lane} h={TL.lane}>
350	          <span style={{ width: 8, height: 8, borderRadius: 2, background: 'var(--f-blue)' }} />
351	          <span style={{ fontSize: 12, fontWeight: 600, color: 'var(--text-primary)' }}>{blueName}</span>
352	        </TrackHead>
353	      </div>
354	
355	      <div ref={scrollRef} className="tl-scroll" style={{ flex: 1, minWidth: 0, overflowX: 'auto', overflowY: 'hidden', position: 'relative' }}>
356	        <div style={{ position: 'relative', width: W, height: totalH, minWidth: '100%' }}>
357	          <div style={{ position: 'absolute', top: TL.ruler, left: 0, width: '100%', height: TL.round, background: 'rgba(255,255,255,0.018)' }} />
358	          <div style={{ position: 'absolute', top: lanesTop + TL.lane, left: 0, width: '100%', height: TL.lane, background: 'rgba(255,255,255,0.022)' }} />
359	
360	          {rounds.map(r => (
361	            <div key={'rb' + r.id}>
362	              {r.round_number > 1 && (
363	                <div style={{ position: 'absolute', top: TL.ruler, left: xFor(r.start_frame), width: 1, height: totalH - TL.ruler, background: 'rgba(255,255,255,0.12)' }} />
364	              )}
365	            </div>
366	          ))}
367	
368	          <div
369	            onPointerDown={startScrub}
370	            className="tl-ruler"
371	            style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: TL.ruler, cursor: 'ew-resize', borderBottom: '1px solid var(--border-glass)' }}
372	          >
373	            {ticks.map(t => (
374	              <div key={t} style={{ position: 'absolute', left: t * pxPerSec, top: 0, height: '100%', pointerEvents: 'none' }}>
375	                <div style={{ position: 'absolute', left: 0, bottom: 0, width: 1, height: 7, background: 'rgba(255,255,255,0.22)' }} />
376	                <span style={{ position: 'absolute', left: 5, top: 5, fontFamily: 'var(--mono)', fontSize: 10, fontWeight: 500, color: 'var(--text-muted)', fontVariantNumeric: 'tabular-nums' }}>{fmtSec(t)}</span>
377	              </div>
378	            ))}
379	          </div>
380	
381	          <div onPointerDown={startScrub} style={{ position: 'absolute', top: TL.ruler, left: 0, width: '100%', height: totalH - TL.ruler, cursor: 'ew-resize', zIndex: 1 }} />
382	
383	          {roundSpans.map(s => (
384	            <SpanBlock key={'rs' + s.id} s={s} top={TL.ruler + 4} h={TL.round - 8} deletable />
385	          ))}
386	
387	          {segs.map(s => {
388	            const c = s.state === 'GROUND' ? 'var(--state-ground)' : s.state === 'CLINCH' ? 'var(--state-clinch)' : 'var(--state-striking)';
389	            const w = Math.max(2, s.t1 * pxPerSec - s.t0 * pxPerSec);
390	            return (
391	              <div
392	                key={'seg' + s.id}
393	                title={s.state}
394	                style={{
