31	import { KEYMAP, colorForAction, iconForAction, successForAction, type Corner, type ToolItem } from '../components/annotate/taxonomy';
32	
33	export default function Annotate() {
34	  const { id } = useParams<{ id: string }>();
35	  const navigate = useNavigate();
36	  const fightId = id ? Number(id) : null;
37	  const { can } = useAuth();
38	
39	  const videoRef = useRef<HTMLVideoElement>(null);
40	  const overlayRef = useRef<FighterOverlayHandle>(null);
41	  const rafRef = useRef<number | null>(null);
42	  const fpsRef = useRef<number>(30);
43	  const lastFrameRef = useRef<number>(-1);
44	  const [isPlaying, setIsPlaying] = useState(false);
45	  const [currentTime, setCurrentTime] = useState(0);
46	  const [duration, setDuration] = useState(0);
47	
48	  const { fights, setFights } = useFights();
49	  const selectedFight = fights.find(f => f.id === fightId) ?? null;
50	  const { events: allEvents, setEvents: setAllEvents } = useEvents(fightId, { source: 'label' });
51	  const events = useMemo(() => allEvents.filter(e => e.kind === 'point'), [allEvents]);
52	  const spans = useMemo(() => allEvents.filter(e => e.kind !== 'point'), [allEvents]);
53	  const { frameMap } = useFighterFrames(fightId);
54	  const { rounds } = useRounds(fightId);
55	  const width = useWindowWidth();
56	  const narrow = width < 1100;
57	
58	  const fps = selectedFight?.fps ?? 30;
59	  fpsRef.current = fps;
60	
61	  const ready = selectedFight !== null && isLabelingReady(selectedFight.state);
62	
63	  useEffect(() => {
64	    const video = videoRef.current;
65	    if (!video || !ready) return;
66	    if (!isPlaying) {
67	      if (rafRef.current !== null) {
68	        video.cancelVideoFrameCallback(rafRef.current);
69	        rafRef.current = null;
70	      }
71	      return;
72	    }
73	    const tick = (_now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
74	      const frame = Math.floor(metadata.mediaTime * fpsRef.current) + 1;
75	      overlayRef.current?.draw(frame);
76	      if (frame !== lastFrameRef.current) {
77	        lastFrameRef.current = frame;
78	        setCurrentTime(metadata.mediaTime);
79	      }
80	      rafRef.current = video.requestVideoFrameCallback(tick);
81	    };
82	    rafRef.current = video.requestVideoFrameCallback(tick);
83	    return () => {
84	      if (rafRef.current !== null) {
85	        video.cancelVideoFrameCallback(rafRef.current);
86	        rafRef.current = null;
87	      }
88	    };
89	  }, [isPlaying, ready]);
90	
91	  const currentFrame = Math.floor(currentTime * fps) + 1;
92	  const currentMs = Math.floor(currentTime * 1000);
93	  const videoSrc = selectedFight ? videoUrl(selectedFight.id) : undefined;
94	
95	  const togglePlay = () => {
96	    const video = videoRef.current;
97	    if (!video) return;
98	    if (isPlaying) video.pause(); else video.play();
99	    setIsPlaying(!isPlaying);
100	  };
101	
102	  const stepFrame = (delta: number) => {
103	    const video = videoRef.current;
104	    if (!video) return;
105	    video.pause();
106	    setIsPlaying(false);
107	    const newTime = Math.min(Math.max(video.currentTime + delta / fps, 0), video.duration);
108	    video.currentTime = newTime;
109	    setCurrentTime(newTime);
110	    overlayRef.current?.draw(Math.floor(newTime * fpsRef.current) + 1);
111	  };
112	
113	  const handleSeek = (time: number) => {
114	    const video = videoRef.current;
115	    if (!video) return;
116	    video.currentTime = time;
117	    setCurrentTime(time);
118	    overlayRef.current?.draw(Math.floor(time * fpsRef.current) + 1);
119	  };
120	
121	  const seekToFrame = (frame: number) => handleSeek(Math.max(0, (frame - 1) / fps));
122	
123	  // The labeller's round spans win over the AI's, which may have collapsed
124	  // the fight into one round. The AI rounds cover the moment before the
125	  // spans have loaded.
126	  const currentRound = spans.find(
127	    s => s.kind === 'round' && s.end_frame != null && currentFrame >= s.frame && currentFrame <= s.end_frame,
128	  )?.value
129	    ?? rounds.find(r => currentFrame >= r.start_frame && currentFrame <= r.end_frame)?.round_number
130	    ?? '-';
131	
132	  const redName = selectedFight?.red_fighter_name ?? 'Red corner';
133	  const blueName = selectedFight?.blue_fighter_name ?? 'Blue corner';
134	
135	  // Reconstructs each point event's display text on the fly (description is
136	  // only ever stored for fight_end) — including the swap-corrected fighter
137	  // name for any event whose own frame falls inside a corner_swap span, so
138	  // reviewing the timeline reflects a swap the moment it's marked, even for
139	  // strikes logged before the span existed.
140	  const cornerSwapSpans = useMemo(
141	    () => spans.filter(s => s.kind === 'corner_swap').map(s => ({ frame: s.frame, end_frame: s.end_frame })),
142	    [spans],
143	  );
144	  const stateMarks = useMemo(() => labelStateMarks(events), [events]);
145	  const describe = (e: Event) => describeEvent(e, {
146	    redName, blueName, swapped: isFrameSwapped(e.frame, cornerSwapSpans),
147	    inClinch: labelStateAt(e.frame, stateMarks) === 'CLINCH',
148	  });
149	
150	  // ---- annotation logging state ----
151	  const [selected, setSelected] = useState<Corner | null>(null);
152	  const [toast, setToast] = useState<{ text: string; color: string; icon: string } | null>(null);
153	  const [flashId, setFlashId] = useState<number | null>(null);
154	  const [hint, setHint] = useState(false);
155	  const [endOpen, setEndOpen] = useState(false);
156	  const [savingCount, setSavingCount] = useState(0);
157	  const [finishing, setFinishing] = useState(false);
158	  const [reopening, setReopening] = useState(false);
159	  const [reopenError, setReopenError] = useState<string | null>(null);
160	  const [confirmDelete, setConfirmDelete] = useState(false);
161	  const [deletingFight, setDeletingFight] = useState(false);
162	  const [deleteError, setDeleteError] = useState<string | null>(null);
163	  // Timeline clip selected by click — Delete removes it. Separate from
164	  // `flashId` (a transient highlight after creation) and from `selected`
165	  // (the red/blue corner for the *next* logged event).
166	  const [selectedEventId, setSelectedEventId] = useState<number | null>(null);
167	
168	  const frameRef = useRef(1);
169	  frameRef.current = currentFrame;
170	  const selRef = useRef<Corner | null>(null);
171	  selRef.current = selected;
172	  const endOpenRef = useRef(false);
173	  endOpenRef.current = endOpen;
174	  const confirmDeleteRef = useRef(false);
175	  confirmDeleteRef.current = confirmDelete;
176	  const selectedEventIdRef = useRef<number | null>(null);
177	  selectedEventIdRef.current = selectedEventId;
178	  const sessionIdsRef = useRef<number[]>([]);
179	
180	  const toastTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
181	  const hintTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
182	  const flashTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
183	
184	  const showToast = (text: string, color: string, icon: string) => {
185	    setToast({ text, color, icon });
186	    clearTimeout(toastTimer.current);
187	    toastTimer.current = setTimeout(() => setToast(null), 1100);
188	  };
189	
190	  const flash = (eventId: number) => {
191	    setFlashId(eventId);
192	    clearTimeout(flashTimer.current);
193	    flashTimer.current = setTimeout(() => setFlashId(null), 700);
194	  };
195	
196	  const addEvent = async (payload: CreateEventPayload) => {
197	    if (!fightId) return null;
198	    setSavingCount(c => c + 1);
199	    try {
200	      const created = await createEvent(fightId, { kind: 'point', ...payload });
201	      setAllEvents(prev => [...prev, created]);
202	      sessionIdsRef.current.push(created.id);
203	      flash(created.id);
