205	    } catch {
206	      showToast('Failed to save event', 'var(--f-red)', 'error');
207	      return null;
208	    } finally {
209	      setSavingCount(c => c - 1);
210	    }
211	  };
212	
213	  const removeEvent = async (eventId: number) => {
214	    if (!fightId) return;
215	    setSavingCount(c => c + 1);
216	    try {
217	      await deleteEvent(fightId, eventId);
218	      setAllEvents(prev => prev.filter(e => e.id !== eventId));
219	      sessionIdsRef.current = sessionIdsRef.current.filter(x => x !== eventId);
