223	    } finally {
224	      setSavingCount(c => c - 1);
225	    }
226	  };
227	
228	  // corner_swap / excluded are start/end toggles: one key opens a span at the
229	  // playhead, the next press of the same key closes it. `openSpanRef` tracks
230	  // the in-flight span id per kind so the second press knows what to close.
231	  const openSpanRef = useRef<Partial<Record<SpanKind, number>>>({});
232	  const SPAN_LABEL: Record<SpanKind, string> = { round: 'Round', corner_swap: 'Corner swap', excluded: 'Excluded' };
233	
234	  // openSpanRef only lives in memory — leaving Annotate and coming back (or a
235	  // reload) resets it to {} even though an unclosed span from the previous
236	  // session is still sitting in the loaded data with end_frame=null. Reseed
237	  // it once that data arrives, or the next O/P press opens a second span
238	  // instead of closing the first.
239	  useEffect(() => {
240	    for (const kind of ['corner_swap', 'excluded'] as const) {
241	      if (openSpanRef.current[kind] != null) continue;
242	      const open = spans.find(s => s.kind === kind && s.end_frame == null);
243	      if (open) openSpanRef.current[kind] = open.id;
244	    }
245	  }, [spans]);
246	
247	  const toggleSpan = async (kind: SpanKind) => {
248	    if (!fightId) return;
249	    const openId = openSpanRef.current[kind];
250	    const frame = frameRef.current;
251	    if (openId != null) {
252	      try {
253	        const start = spans.find(s => s.id === openId)?.frame ?? frame;
254	        const patch = frame < start ? { frame, end_frame: start } : { end_frame: frame };
255	        const updated = await updateEvent(fightId, openId, patch);
256	        setAllEvents(prev => prev.map(s => (s.id === openId ? updated : s)));
257	        showToast(`${SPAN_LABEL[kind]} span closed`, 'var(--slate-400)', 'flag');
258	      } catch {
259	        showToast('Failed to close span', 'var(--f-red)', 'error');
260	      } finally {
261	        delete openSpanRef.current[kind];
262	      }
263	      return;
264	    }
265	    try {
266	      const created = await createEvent(fightId, {
267	        kind, frame, value: kind === 'excluded' ? 'replay' : null,
268	      });
269	      setAllEvents(prev => [...prev, created]);
270	      openSpanRef.current[kind] = created.id;
271	      showToast(`${SPAN_LABEL[kind]} span opened`, 'var(--slate-400)', 'flag');
272	    } catch {
273	      showToast('Failed to open span', 'var(--f-red)', 'error');
274	    }
275	  };
276	
277	  const updateSpan = async (spanId: number, patch: { frame?: number; end_frame?: number }) => {
278	    if (!fightId) return;
279	    try {
280	      const updated = await updateEvent(fightId, spanId, patch);
281	      setAllEvents(prev => prev.map(s => (s.id === spanId ? updated : s)));
282	    } catch {
283	      showToast('Failed to update span', 'var(--f-red)', 'error');
284	    }
285	  };
286	
287	  const removeSpan = async (spanId: number) => {
288	    if (!fightId) return;
289	    try {
290	      await deleteEvent(fightId, spanId);
291	      setAllEvents(prev => prev.filter(s => s.id !== spanId));
292	      for (const [kind, id] of Object.entries(openSpanRef.current)) {
293	        if (id === spanId) delete openSpanRef.current[kind as SpanKind];
294	      }
295	      if (spans.find(s => s.id === spanId)?.kind === 'round') {
296	        await renumberRounds(spans.filter(s => s.kind === 'round' && s.id !== spanId));
297	      }
298	    } catch {
299	      showToast('Failed to delete span', 'var(--f-red)', 'error');
300	    }
301	  };
302	
303	  // A round span's `value` is its round number, which eval and export read.
304	  // Keep it equal to the span's position in time, so adding or deleting a
305	  // round renumbers the ones after it.
306	  const renumberRounds = async (roundSpans: Event[]) => {
307	    if (!fightId) return;
308	    const stale = [...roundSpans]
309	      .sort((a, b) => a.frame - b.frame)
310	      .map((s, i) => ({ s, value: String(i + 1) }))
311	      .filter(({ s, value }) => s.value !== value);
312	    const updated = await Promise.all(stale.map(({ s, value }) => updateEvent(fightId, s.id, { value })));
313	    const byId = new Map(updated.map(u => [u.id, u]));
314	    setAllEvents(prev => prev.map(e => byId.get(e.id) ?? e));
315	  };
316	
317	  // K starts a new round at the playhead. Inside a round span it splits that
318	  // span there, which is how a fight that segmentation collapsed into one
319	  // round gets its real rounds back. Outside every round it adds one running
320	  // up to the next round (or the end of the video). Either way the labeller
321	  // then drags the edges to cut out the break between rounds.
322	  const addRound = async () => {
323	    if (!fightId) return;
324	    const frame = frameRef.current;
325	    const roundSpans = spans.filter(s => s.kind === 'round');
326	    const containing = roundSpans.find(s => s.end_frame != null && s.frame <= frame && frame <= s.end_frame);
327	    if (containing?.frame === frame) {
328	      showToast('A round already starts here', 'var(--f-red)', 'error');
329	      return;
330	    }
331	    const nextStart = Math.min(...roundSpans.filter(s => s.frame > frame).map(s => s.frame));
332	    const end = containing?.end_frame
333	      ?? (Number.isFinite(nextStart) ? nextStart - 1 : Math.max(frame, Math.floor(duration * fps)));
334	    setSavingCount(c => c + 1);
335	    try {
336	      let next = roundSpans;
337	      if (containing) {
338	        const shortened = await updateEvent(fightId, containing.id, { end_frame: frame - 1 });
339	        next = next.map(s => (s.id === shortened.id ? shortened : s));
340	        setAllEvents(prev => prev.map(e => (e.id === shortened.id ? shortened : e)));
341	      }
342	      const created = await createEvent(fightId, { kind: 'round', frame, end_frame: end });
343	      setAllEvents(prev => [...prev, created]);
344	      await renumberRounds([...next, created]);
345	      showToast(containing ? 'Round split at playhead' : 'Round added', 'var(--green-500)', 'flag');
346	    } catch {
347	      showToast('Failed to add round', 'var(--f-red)', 'error');
348	    } finally {
349	      setSavingCount(c => c - 1);
350	    }
351	  };
