367	      return;
368	    }
369	    // Fighter-independent tools (fight state) must not pick up whichever corner
370	    // happens to be selected — neither in the stored corner nor in the toast.
371	    const cornerIdx = item.needsFighter ? (corner === 'red' ? 0 : 1) : null;
372	    const fighterName = item.needsFighter ? (corner === 'red' ? redName : blueName) : '';
373	    const target = item.hasTarget ? (shiftKey ? 'body' : 'head') : item.fixedTarget ?? null;
374	    // `description` is only kept as a local for the toast text below — it's
375	    // no longer sent to the backend. Every action here except fight_end is
376	    // fully reconstructable from action/target/corner (see describeEvent.ts),
377	    // so storing a frozen copy would only go stale the next time a
378	    // corner_swap span is added or edited.
379	    const description = item.text(fighterName, target ?? undefined, labelStateAt(frameRef.current, stateMarks) === 'CLINCH');
