const of = window.fetch; window.fetch = async (u, o) => { if (o && o.method === 'PUT') await new Promise(r=>setTimeout(r,800)); return of(u, o); };
const seg = () => document.querySelector('button[title="GROUND"], button[title^="GROUND ·"]');
const g = seg(); g.scrollIntoView({block:'center'}); await new Promise(r=>setTimeout(r,300));
const h = g.querySelector('[title="Drag to move where this state starts"]');
const r0 = h.getBoundingClientRect(); const x0 = r0.x + r0.width/2, y = r0.y + r0.height/2;
const opts = (x) => ({bubbles:true, clientX:x, clientY:y, pointerId:1, isPrimary:true});
h.dispatchEvent(new PointerEvent('pointerdown', opts(x0)));
for (let i=1;i<=10;i++) { window.dispatchEvent(new PointerEvent('pointermove', opts(x0 - i*6))); await new Promise(r=>requestAnimationFrame(r)); }
const during = seg().getBoundingClientRect().x;
window.dispatchEvent(new PointerEvent('pointerup', opts(x0 - 60)));
await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
const justAfter = seg().getBoundingClientRect().x;
await new Promise(r=>setTimeout(r,1200));
const settled = seg().getBoundingClientRect().x;
window.fetch = of;
({start: r0.x, during, justAfter, settled})

